import {estimateFooterHtml,separateCostToolbar} from './estimate-footer.js';
import {costScopeLabels,separateSectionLabel} from './cost-scopes.js';
import {surchargeBidLabel,surchargeBidHint} from './surcharge-display.js';
import {amount,appliedRate,bidPercent} from './calc.js';
import {pendingAuto} from './auto-link.js';
export function estimateGrid(lines,{selectedLineId,subtotals,hierarchy,esc,num,money,directTotal=null,project=null}){
 const costs=['labor','material','expense',...(lines.some(l=>l.rate?.other||subtotals.get(l.id)?.other)?['other']:[])],labels={labor:'노무비',material:'재료비',expense:'경비',other:'기타'};
 const actions=l=>`<td><div class="row-actions"><button class="button small" data-copy="${l.id}" ${l.generatedSupplyFee?'disabled':''} aria-label="${esc(l.name)} 복사">복사</button><button class="button small" data-move-up="${l.id}" ${l.generatedSupplyFee?'disabled':''} aria-label="${esc(l.name)} 위로">↑</button><button class="button small" data-move-down="${l.id}" ${l.generatedSupplyFee?'disabled':''} aria-label="${esc(l.name)} 아래로">↓</button><button class="delete-btn" data-delete="${l.id}" aria-label="${esc(l.name)} 삭제">×</button></div></td>`;
 const footer=project?estimateFooterHtml(project,costs,{esc,money,computedTotals:directTotal??undefined}):'';let footerShown=false;
 const fixed=['포함','L','공종','품 명','규 격','수 량','단위','연결'];
 return `<table class="est-grid"><thead><tr><th rowspan="2" class="row-selector-head"><button data-select-all aria-label="현재 표시된 행 전체 선택" title="전체 선택">No.</button></th>${fixed.map(t=>`<th rowspan="2">${t}</th>`).join('')}<th colspan="2">합 계</th>${costs.map(k=>`<th colspan="2" data-cost-key="${k}">${labels[k]}</th>`).join('')}<th rowspan="2">낙찰률 %</th><th rowspan="2">계상 구분</th><th rowspan="2">행 편집</th></tr><tr><th>단 가</th><th>금 액</th>${costs.map(k=>`<th data-unit-cost-key="${k}">단 가</th><th data-cost-key="${k}">금 액</th>`).join('')}</tr></thead><tbody>${lines.map((l,index)=>{
 const a=l.level?subtotals.get(l.id):amount(l),rate=l.rate?appliedRate(l):null;
 const atBoundary=l.bucket!=='direct'&&(index===0||lines[index-1].bucket==='direct')&&!lines.slice(index).some(x=>!x.level&&x.bucket==='direct');
 const boundary=atBoundary&&!footerShown?(footerShown=true,footer):'';
 const prefix=boundary+`<tr data-id="${l.id}" data-level="${l.level||0}" title="${esc(l.source||'직접 입력')}" class="${l.exclude?'row-excluded ':''}${l.level?'heading-row ':!a?'unconfirmed-row ':''}${selectedLineId===l.id?'selected-line':''}"><td class="row-selector"><button data-select-row="${l.id}" aria-label="${index+1}행 선택" title="${index+1}행 · Shift 범위 / Ctrl 추가 선택">${index+1}</button></td><td class="cell-center">${l.level?`<button class="fold-heading" data-fold="${l.id}" aria-label="${esc(l.name)} ${l.collapsed?'펼치기':'접기'}" aria-expanded="${!l.collapsed}">${l.collapsed?'▸':'▾'}</button>`:`<input type="checkbox" data-field="include" ${!l.exclude?'checked':''} aria-label="${esc(l.name)} 포함">`}</td><td class="level-cell"><input type="number" min="0" max="9" step="1" data-field="level" ${l.generatedSupplyFee?'readonly':''} value="${l.level||0}" aria-label="${esc(l.name)} 레벨"></td><td><textarea class="cell-input grid-group" data-field="group" ${l.generatedSupplyFee?'readonly':''} aria-label="공종" rows="1">${esc(l.group)}</textarea>${l.bucket!=='direct'&&separateSectionLabel(l)?`<small>${esc(separateSectionLabel(l))}</small>`:''}</td><td class="row-name" style="padding-left:${4+(hierarchy.get(l.id)?.depth||0)*10}px"><input class="cell-input cell-name" data-field="name" ${l.generatedSupplyFee?'readonly':''} value="${esc(l.name)}" aria-label="품명"></td>`;
 if(l.level){const titleCell=`<td colspan="5" class="heading-title" style="padding-left:${4+(hierarchy.get(l.id)?.depth||0)*10}px"><textarea class="cell-input heading-name" data-field="name" aria-label="품명" rows="${Math.max(1,Math.ceil(l.name.length/38))}">${esc(l.name)}</textarea><small data-heading-note>${l.separateTail&&separateSectionLabel(l)?esc(separateSectionLabel(l))+' · ':''}L${l.level} ${l.level===2?'공구 합계':'공종 소계'}${l.bucket!=='direct'?' · '+costScopeLabels[l.bucket]+' · 원가 자동 연결':''}${a.missing?` · 미확정 ${a.missing}건`:''}</small></td>`;return prefix.slice(0,prefix.lastIndexOf('<td class="row-name"'))+titleCell+`<td></td><td class="number line-total" data-heading-total>${money(a.total)}</td>${costs.map(k=>`<td data-unit-cost-key="${k}"></td><td class="number" data-cost-key="${k}">${money(a[k])}</td>`).join('')}<td></td><td><select data-field="bucket" aria-label="${esc(l.name)} 공종 계상 구분">${Object.entries(costScopeLabels).map(([v,n])=>`<option value="${v}" ${l.bucket===v?'selected':''}>${n}</option>`).join('')}</select></td>${actions(l)}</tr>`;}

 return prefix+`<td><input class="cell-input cell-spec" data-field="spec" ${l.generatedSupplyFee?'readonly':''} value="${esc(l.spec)}" aria-label="규격"></td><td class="number cell-quantity"><input class="cell-input" data-field="qty" type="number" min="${l.deduction?'-100000000000000':'0'}" step="any" value="${l.qty??''}" ${l.generatedSupplyFee?'readonly title="동일 신청·설계·검사 각각 1건"':''} aria-label="${esc(l.name)} 수량"></td><td class="cell-center"><input class="cell-input cell-unit" data-field="unit" ${l.generatedSupplyFee?'readonly':''} value="${esc(l.unit)}" aria-label="단위"></td><td class="cell-center"><button ${l.generatedSupplyFee?'data-supply-fees':l.surcharge?`data-adjustment-edit="${l.id}"`:""} class="status-button ${pendingAuto(l)?'auto-connected':l.status==='confirmed'?'confirmed':''}" ${l.generatedSupplyFee||l.surcharge?'':`data-match="${l.id}"`} title="${esc(l.rate?l.rate.source+' · '+l.rate.code:'단가 연결')}">${l.generatedSupplyFee?'수수료 설정':l.surcharge?'할증 설정':pendingAuto(l)?'자동':l.status==='confirmed'?'연결됨':l.status==='proposed'?'미확정 · 후보':'미확정 · 연결'}</button></td><td class="number unit-cost">${l.manualSeparate?`<input class="cell-input" type="number" min="0" step="any" data-separate-price value="${l.rate?.total||0}" aria-label="${esc(l.name)} 직접 단가">`:rate?`<button class="mini-link" data-detail-line="${l.id}">${num(rate.total)}</button>`:'—'}</td><td class="number line-total">${a?money(a.total):'<span class="error-text">미확정</span>'}</td>${costs.map(k=>`<td class="number unit-cost" data-unit-cost-key="${k}">${rate?num(rate[k]):'—'}</td><td class="number cost-cell" data-cost-key="${k}">${a?money(a[k]):'—'}</td>`).join('')}<td class="cell-center">${l.surcharge?`<span class="surcharge-bid-label" title="${esc(surchargeBidHint(l))}">${esc(surchargeBidLabel(l))}</span>`:`<button class="mini-link" data-bid-line="${l.id}" title="낙찰률 검토">${l.rate?.evidenceBid?'근거 '+num(l.rate.evidenceBid.percent):num(bidPercent(l))}</button>`}</td><td class="cell-center"><select class="bucket" data-field="bucket" ${l.generatedSupplyFee?'disabled':''} aria-label="계상 구분">${[['direct','직접공사비'],['government','관급자재'],['waste','별도 · 부가세만'],['fees','수수료·부담금']].map(([v,n])=>`<option value="${v}" ${l.bucket===v?'selected':''}>${n}</option>`).join('')}</select></td>${actions(l)}</tr>`;
 }).join('')}${footerShown?'':footer}${project?separateCostToolbar(project,14+costs.length*2,esc):''}</tbody></table>`;
}
